from __future__ import annotations

from io import BytesIO
from pathlib import Path
from uuid import uuid4
from zipfile import BadZipFile, ZipFile

from docx import Document

from app.db import connect
from app.settings import settings

MAX_TEMPLATE_BYTES = 10 * 1024 * 1024
MAX_UNCOMPRESSED_BYTES = 40 * 1024 * 1024


def template_directory() -> Path:
    return settings.data_dir / "templates"


def template_path(template: dict) -> Path:
    # The stored name is generated by the server, never taken from an upload.
    name = str(template["stored_name"])
    if len(name) != 37 or not name.endswith(".docx") or any(c not in "0123456789abcdef" for c in name[:-5]):
        raise ValueError("模板文件名无效")
    return template_directory() / name


def inspect_template(blob: bytes) -> list[str]:
    if not blob or len(blob) > MAX_TEMPLATE_BYTES:
        raise ValueError("模板文件不能为空且不能超过 10 MB")
    try:
        with ZipFile(BytesIO(blob)) as archive:
            members = archive.infolist()
            if len(members) > 1000 or sum(part.file_size for part in members) > MAX_UNCOMPRESSED_BYTES:
                raise ValueError("模板解压后内容过大")
            if "word/document.xml" not in archive.namelist():
                raise ValueError("文件不是有效的 DOCX")
        document = Document(BytesIO(blob))
    except (BadZipFile, KeyError, OSError, ValueError) as exc:
        if isinstance(exc, ValueError):
            raise
        raise ValueError("文件不是有效的 DOCX") from exc
    except Exception as exc:
        raise ValueError("无法读取 DOCX 内容") from exc

    paragraphs = [p.text.strip() for p in document.paragraphs]
    if not any("yyyy年mm月dd日" in p or "yyyy-mm-dd" in p for p in paragraphs):
        raise ValueError("模板正文需要包含 yyyy年mm月dd日 或 yyyy-mm-dd 日期占位符")
    periods: dict[str, list[str]] = {"上午": [], "下午": []}
    current = ""
    from app.report import normalize_section_name

    for label in paragraphs:
        if label.startswith("巡检时间："):
            current = "上午" if "上午" in label else "下午" if "下午" in label else ""
        elif current and label and label[0].isdigit():
            periods[current].append(label)
    if not periods["上午"] or not periods["下午"]:
        raise ValueError("模板需要包含“巡检时间：上午”和“巡检时间：下午”及各自的数字开头章节")
    morning = [normalize_section_name(s) for s in periods["上午"]]
    afternoon = [normalize_section_name(s) for s in periods["下午"]]
    if len(set(morning)) != len(morning) or len(set(afternoon)) != len(afternoon):
        raise ValueError("同一时段不能有重复章节")
    if set(morning) != set(afternoon):
        raise ValueError("上午和下午的章节必须一致")
    return periods["上午"]


def list_templates() -> list[dict]:
    with connect() as conn:
        rows = conn.execute("SELECT * FROM report_templates ORDER BY id DESC").fetchall()
    return [dict(row) for row in rows]


def get_template(template_id: int) -> dict | None:
    with connect() as conn:
        row = conn.execute("SELECT * FROM report_templates WHERE id = ?", (template_id,)).fetchone()
    return dict(row) if row else None


def create_template(name: str, original_name: str, blob: bytes) -> dict:
    name = name.strip()
    if not name or len(name) > 100:
        raise ValueError("模板名称长度需为 1 到 100 个字符")
    if not original_name.lower().endswith(".docx"):
        raise ValueError("只支持上传 .docx 文件")
    inspect_template(blob)
    directory = template_directory()
    directory.mkdir(parents=True, exist_ok=True)
    stored_name = f"{uuid4().hex}.docx"
    path = directory / stored_name
    with path.open("xb") as file:
        file.write(blob)
    try:
        with connect() as conn:
            cursor = conn.execute(
                "INSERT INTO report_templates (name, stored_name, original_name) VALUES (?, ?, ?)",
                (name, stored_name, Path(original_name).name),
            )
            template_id = int(cursor.lastrowid)
    except Exception:
        path.unlink(missing_ok=True)
        raise
    return get_template(template_id) or {}


def delete_template(template_id: int) -> bool:
    template = get_template(template_id)
    if template is None:
        raise ValueError("模板不存在")
    with connect() as conn:
        count = conn.execute("SELECT COUNT(*) FROM report_jobs WHERE template_id = ?", (template_id,)).fetchone()[0]
        if count:
            raise ValueError(f"有 {count} 个巡检任务正在使用此模板，请先修改任务")
        conn.execute("DELETE FROM report_templates WHERE id = ?", (template_id,))
    template_path(template).unlink(missing_ok=True)
    return True
